function icon(n){return `<svg viewBox="0 0 24 24">${ICONS[n]||ICONS.spark}</svg>`} function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon))}
function theme(){const t=localStorage.getItem(THEME_KEY)||state.theme||'system';return t==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):t} function applyTheme(){document.body.classList.toggle('dark',theme()==='dark');document.getElementById('themeToggle').innerHTML=icon(theme()==='dark'?'sun':'spark')}
function global(){const all=allSets();let total=0,seen=0,correct=0,due=0,learned=0;all.forEach(s=>s.cards.forEach(c=>{total++;const st=state.cardStats[c.id];if(st?.seen){seen++;correct+=st.correct||0;if(st.dueAt<=now())due++;if((st.streak||0)>=3)learned++}}));return{total,seen,correct,due,learned,accuracy:pct(correct,seen)}}
function stat(id){return state.cardStats[id]||{seen:0,correct:0,wrong:0,streak:0,interval:0,ease:2.3,dueAt:0,last:0}}
function answer(card,grade){const s=stat(card.id);s.seen++;if(grade==='again'||grade==='hard')s.wrong++;else s.correct++;if(grade==='again'){s.streak=0;s.interval=0;s.ease=Math.max(1.3,(s.ease||2.3)-.15);s.dueAt=now()+days(.01)}else{const mult=grade==='easy'?Math.min(4,(s.ease||2.3)+.15):grade==='good'?(s.ease||2.3):Math.max(1.3,(s.ease||2.3)-.05);s.ease=mult;s.streak=(s.streak||0)+1;s.interval=s.interval?Math.max(1,Math.round(s.interval*mult)):grade==='easy'?4:1;s.dueAt=now()+days(s.interval)}s.last=now();state.cardStats[card.id]=s;save()}
function dueCards(){return allSets().flatMap(s=>s.cards.map(c=>({c,s}))).filter(x=>stat(x.c.id).seen&&stat(x.c.id).dueAt<=now()).sort((a,b)=>stat(a.c.id).dueAt-stat(b.c.id).dueAt)}
function home(){const g=global(), due=dueCards(), today=new Date().toDateString();const todayAns=state.sessions.filter(x=>new Date(x.date).toDateString()===today).reduce((a,x)=>a+x.answers,0);document.getElementById('view-home').innerHTML=`<div class="hero"><span class="eyebrow">СИСТЕМА ЗНАНИЙ · BETA 2.0</span><h1>Учись эффективно с AlmazovQwiz</h1><p>Карточки, учебники, интервальное повторение и аналитика в одной системе. Все знания связаны между собой и сохраняются локально.</p><div class="hero-actions"><button class="btn primary" onclick="openStudy('temporal','cards')">${icon('cards')} Продолжить обучение</button><button class="btn" onclick="showView('knowledge')">${icon('brain')} Карта знаний</button></div></div>
<div class="section"><div class="section-head"><div><h2>Быстрые действия</h2><p>Основные инструменты платформы</p></div></div><div class="grid grid-4"><div class="action-card" onclick="showView('create')"><div class="action-icon">${icon('plus')}</div><div><strong>Создать набор</strong><small>Вручную или из текста</small></div></div><div class="action-card" onclick="showView('textbook')"><div class="action-icon">${icon('book')}</div><div><strong>Добавить учебник</strong><small>PDF, DOCX или TXT</small></div></div><div class="action-card" onclick="startDue()"><div class="action-icon">${icon('brain')}</div><div><strong>Повторить знания</strong><small>${due.length?due.length+' карточек ждут вас':'Пока всё повторено'}</small></div></div><div class="action-card" onclick="showView('analytics')"><div class="action-icon">${icon('chart')}</div><div><strong>Аналитика</strong><small>Ошибки и динамика</small></div></div></div></div>
<div class="section"><div class="section-head"><div><h2>Сегодня</h2><p>${todayAns} реальных ответов · цель ${state.profile.dailyGoal}</p></div></div><div class="stats-grid"><div class="stat"><small>Освоено</small><strong>${g.learned}</strong><span class="delta">${g.learned?'Устойчивые знания':'Пока нет'}</span></div><div class="stat"><small>Новые</small><strong>${g.total-g.seen}</strong><span class="muted">не отвечались</span></div><div class="stat"><small>К повторению</small><strong>${g.due}</strong><span class="${g.due?'warn':'good'}">${g.due?'требуют внимания':'всё в порядке'}</span></div><div class="stat"><small>Точность</small><strong>${g.accuracy}%</strong><span class="muted">только реальные ответы</span></div></div></div>
<div class="section"><div class="section-head"><div><h2>Основные предметы</h2><p>Организуй знания по дисциплинам</p></div></div><div class="grid grid-4">${SUBJECTS.map(([s,i])=>`<div class="subject-card" onclick="showView('sets');document.getElementById('setSubject').value='${s}';setsView()"><div class="subject-icon">${icon(i)}</div><b>${s}</b><small>${allSets().filter(x=>x.subject===s).length} набора</small></div>`).join('')}</div></div>
<div class="section"><div class="section-head"><div><h2>Мои наборы</h2><p>Продолжите с места, где остановились</p></div><button class="btn soft" onclick="showView('sets')">Все наборы</button></div><div class="grid grid-4">${allSets().slice(0,4).map(setCard).join('')}</div></div>`;hydrateIcons()}
function setProgress(s){const vals=s.cards.map(c=>stat(c.id));return pct(vals.filter(x=>x.streak>=3).length,s.cards.length)}
function setCard(s){const p=setProgress(s);return `<article class="set-card"><div class="set-cover">${icon(s.subject==='Анатомия'?'bone':s.subject==='Гистология'?'cell':s.subject==='Биология'?'dna':'latin')}</div><div class="set-meta"><span class="tag">${esc(s.subject)}</span><span class="tag">${s.cards.length} карточек</span></div><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><div class="set-footer"><div class="progress"><span style="width:${p}%"></span></div><small>${p}%</small><button class="btn primary" onclick="openStudy('${s.id}','cards')">${p?'Продолжить':'Начать'}</button></div></article>`}
function setsView(query=''){const q=(query||'').toLowerCase();let sets=allSets().filter(s=>(!q||(s.title+s.subject+s.description+s.tags.join(' ')).toLowerCase().includes(q)));document.getElementById('view-sets').innerHTML=`<h1 class="page-title">Мои наборы</h1><p class="page-sub">Каждый набор связан с системой знаний и статистикой карточек.</p><div class="toolbar"><div class="search-wrap"><i data-icon="search"></i><input id="setSearch" value="${esc(query)}" placeholder="Поиск по наборам…"></div><select class="select" id="setSubject"><option value="">Все предметы</option>${SUBJECTS.map(x=>`<option>${x[0]}</option>`).join('')}</select><button class="btn primary" onclick="showView('create')">${icon('plus')} Создать</button></div><div class="tabs"><button class="tab active">Все</button><button class="tab">Изучаю</button><button class="tab">Избранное</button><button class="tab">На повторение</button></div><div id="setsGrid" class="grid grid-3">${sets.map(setCard).join('')}</div>`;hydrateIcons();document.getElementById('setSearch').oninput=e=>setsView(e.target.value);document.getElementById('setSubject').onchange=e=>{const v=e.target.value;document.getElementById('setsGrid').innerHTML=allSets().filter(s=>!v||s.subject===v).map(setCard).join('');hydrateIcons()}}
function openStudy(setId,mode='cards'){current={setId,index:0,mode,revealed:false,session:{answers:0,correct:0,mode,date:now()}};showView('study')}
function startDue(){const d=dueCards()[0];if(!d){toast('Карточек к повторению пока нет');return}current={setId:d.s.id,index:d.s.cards.findIndex(c=>c.id===d.c.id),mode:'cards',revealed:false,session:{answers:0,correct:0,mode:'cards',date:now()},options:null};showView('study')}
function currentCard(){const s=getSet(current.setId);return s?.cards[current.index%s.cards.length]}
function studyView(){const s=getSet(current.setId)||DEFAULT_SETS[0],c=currentCard();if(!c)return;const total=s.cards.length,kind=c.kind||'basic';let body='';const src=c.source?`<div class="card-source">${icon('book')}<span>${esc(c.source.name)} · ${esc(c.source.chapterTitle||'раздел')}</span></div>`:'';const img=c.image?`<div class="study-image"><img src="${esc(c.image)}" alt="Иллюстрация из учебника"></div>`:'';if(current.mode==='cards'||current.mode==='learn'){body=`<div class="flashcard ${kind==='image_mcq'?'visual-card':''}"><div class="type">${kind==='image_mcq'?'ВИЗУАЛЬНАЯ КАРТОЧКА':current.mode==='learn'?'ИЗУЧЕНИЕ':'КАРТОЧКИ'} · ${current.index+1}/${total}</div>${img}<h2>${esc(c.q)}</h2>${src}<div class="answer ${current.revealed?'':'hidden'}"><span class="eyebrow">ОТВЕТ</span><p>${esc(c.a)}</p></div>${current.revealed?'':'<button class="btn primary" onclick="reveal()">Показать ответ</button>'}</div>${current.revealed?`<div class="study-actions"><button class="grade again" onclick="grade('again')">Снова<small>короткий интервал</small></button><button class="grade hard" onclick="grade('hard')">Сложно<small>повторить раньше</small></button><button class="grade good" onclick="grade('good')">Хорошо<small>обычный интервал</small></button><button class="grade easy" onclick="grade('easy')">Легко<small>длинный интервал</small></button></div>`:''}`}else if(current.mode==='write'){body=`<div class="flashcard">${img}<div class="type">НАПИСАНИЕ · ${current.index+1}/${total}</div><h2>${esc(c.q)}</h2>${src}<div class="write-box"><input id="writeAnswer" placeholder="Введите ответ…" autocomplete="off"><button class="btn primary" onclick="checkWrite()">Проверить</button></div><div id="writeResult"></div></div>`}else if(current.mode==='test'||current.mode==='exam'){current.options=current.options||c.options||makeOptions(s,c);const opts=current.options;body=`<div class="flashcard ${kind==='image_mcq'?'visual-card':''}">${img}<div class="type">${current.mode==='exam'?'ЭКЗАМЕН':'ТЕСТ'} · ${current.index+1}/${total}</div><h2>${esc(c.q)}</h2>${src}<div class="quiz-options">${opts.map((o,i)=>`<button class="option" onclick="chooseOption(${i})">${String.fromCharCode(65+i)} · ${esc(o)}</button>`).join('')}</div></div>`}document.getElementById('view-study').innerHTML=`<div class="study-shell"><div class="study-head"><div><button class="btn soft" onclick="finishSession();showView('sets')">← Наборы</button><h2>${esc(s.title)}</h2><small class="muted">${esc(s.subject)} · ${current.mode==='write'?'Написание':current.mode==='test'?'Тест':current.mode==='exam'?'Экзамен':current.mode==='learn'?'Изучение':'Карточки'}</small></div><select class="select" onchange="switchMode(this.value)"><option value="cards" ${current.mode==='cards'?'selected':''}>Карточки</option><option value="learn" ${current.mode==='learn'?'selected':''}>Изучение</option><option value="write" ${current.mode==='write'?'selected':''}>Написание</option><option value="test" ${current.mode==='test'?'selected':''}>Тест</option><option value="exam" ${current.mode==='exam'?'selected':''}>Экзамен</option></select></div><div class="study-progress"><span style="width:${pct(current.index,total)}%"></span></div>${body}<div class="form-note">Открытие карточки не меняет прогресс. Состояние знания изменяется только после ответа.</div></div>`;hydrateIcons()}
function reveal(){current.revealed=true;studyView()} function grade(g){const c=currentCard();answer(c,g);current.session.answers++;if(g==='good'||g==='easy')current.session.correct++;nextCard()} function nextCard(){current.index++;current.revealed=false;current.options=null;if(current.index>=getSet(current.setId).cards.length){finishSession();toast('Сессия завершена');showView('sets')}else studyView()}
function finishSession(){if(current.session&&current.session.answers){state.sessions.unshift({...current.session});state.sessions=state.sessions.slice(0,100);save()}current.session=null}
function makeOptions(s,c){const pool=s.cards.filter(x=>x.id!==c.id).map(x=>x.a).sort(()=>Math.random()-.5).slice(0,3);return[c.a,...pool].sort(()=>Math.random()-.5)}
function chooseOption(i){const s=getSet(current.setId),c=currentCard(),opts=current.options||makeOptions(s,c),buttons=[...document.querySelectorAll('.option')];const right=opts[i]===c.a;buttons.forEach((b,n)=>{b.disabled=true;if(opts[n]===c.a)b.classList.add('correct');if(n===i&&!right)b.classList.add('wrong')});answer(c,right?'good':'again');current.session.answers++;if(right)current.session.correct++;setTimeout(nextCard,550)}
function checkWrite(){const c=currentCard(),v=document.getElementById('writeAnswer').value.trim().toLowerCase(),a=c.a.trim().toLowerCase();const exact=v===a||a.includes(v)&&v.length>5;const r=document.getElementById('writeResult');r.innerHTML=`<div class="result-box"><b class="${exact?'good':'bad'}">${exact?'Правильно':'Нужно повторить'}</b><p>${esc(c.a)}</p></div>`;answer(c,exact?'good':'again');current.session.answers++;if(exact)current.session.correct++;setTimeout(nextCard,900)}
function switchMode(m){current.mode=m;current.index=0;current.revealed=false;showView('study')}
function knowledgeView(){const g=global(), sets=allSets();document.getElementById('view-knowledge').innerHTML=`<h1 class="page-title">Карта знаний</h1><p class="page-sub">Прогресс основан только на реальных ответах и устойчивости знаний.</p><div class="stats-grid"><div class="stat"><small>Общий прогресс</small><strong>${pct(g.learned,g.total)}%</strong><span class="muted">${g.learned} устойчивых из ${g.total}</span></div><div class="stat"><small>Новые</small><strong>${g.total-g.seen}</strong><span class="muted">нет ответов</span></div><div class="stat"><small>В изучении</small><strong>${Math.max(0,g.seen-g.learned)}</strong><span class="muted">нужно закреплять</span></div><div class="stat"><small>К повторению</small><strong>${g.due}</strong><span class="${g.due?'warn':'good'}">${g.due?'есть задания':'нет заданий'}</span></div></div><div class="section grid grid-2"><div class="knowledge-map"><div class="knowledge-core">АНАТОМИЯ<br><small>${setProgress(getSet('temporal'))}%</small></div>${[['Височная кость',setProgress(getSet('temporal')),'n1'],['Череп',setProgress(getSet('skull')),'n2'],['Позвоночник',setProgress(getSet('spine')),'n3'],['Клеточный цикл',setProgress(getSet('cell')),'n4'],['Кровь',setProgress(getSet('histology')),'n5']].map(x=>`<div class="knowledge-node ${x[2]}"><b>${x[0]}</b><small>${x[1]}%</small></div>`).join('')}</div><div class="panel"><div class="section-head"><div><h3>Состояние наборов</h3><p>Новые знания не выдаются за изученные автоматически.</p></div></div><table class="table"><thead><tr><th>Набор</th><th>Карточек</th><th>Устойчивые</th><th>Повторение</th></tr></thead><tbody>${sets.map(s=>{const vals=s.cards.map(c=>stat(c.id));return `<tr><td>${esc(s.title)}</td><td>${s.cards.length}</td><td class="score">${vals.filter(x=>x.streak>=3).length}</td><td class="warn">${vals.filter(x=>x.seen&&x.dueAt<=now()).length}</td></tr>`}).join('')}</tbody></table></div></div>`}
function analyticsView(){const g=global();const recent=state.sessions.slice(0,14).reverse();document.getElementById('view-analytics').innerHTML=`<h1 class="page-title">Аналитика</h1><p class="page-sub">Фактическая история ответов, ошибок и повторений.</p><div class="stats-grid"><div class="stat"><small>Ответов</small><strong>${g.seen}</strong><span class="muted">за всё время</span></div><div class="stat"><small>Правильность</small><strong>${g.accuracy}%</strong><span class="muted">по реальным ответам</span></div><div class="stat"><small>Устойчивые</small><strong>${g.learned}</strong><span class="muted">серия ≥ 3</span></div><div class="stat"><small>Сессий</small><strong>${state.sessions.length}</strong><span class="muted">сохранено локально</span></div></div><div class="section grid grid-2"><div class="panel"><div class="section-head"><div><h3>Динамика сессий</h3><p>Количество ответов и точность</p></div></div>${recent.length?recent.map(x=>`<div class="settings-row"><span>${new Date(x.date).toLocaleDateString('ru-RU')} · ${x.mode}</span><span><b>${x.correct}/${x.answers}</b> · ${pct(x.correct,x.answers)}%</span></div>`).join(''):'<div class="empty">Здесь появится история после первой учебной сессии.</div>'}</div><div class="panel"><div class="section-head"><div><h3>Слабые знания</h3><p>Карточки с ошибками и короткой устойчивостью</p></div></div>${allSets().flatMap(s=>s.cards.map(c=>({c,s,st:stat(c.id)}))).filter(x=>x.st.wrong).sort((a,b)=>b.st.wrong-a.st.wrong).slice(0,8).map(x=>`<div class="settings-row"><span>${esc(x.c.q.slice(0,65))}</span><span class="bad">${x.st.wrong} ошибок</span></div>`).join('')||'<div class="empty">Пока нет ошибок — здесь будут реальные слабые места.</div>'}</div></div>`}
async function textbookView(){document.getElementById('view-textbook').innerHTML=`<h1 class="page-title">Учебник</h1><p class="page-sub">Оцифруйте источник, читайте главы внутри AlmazovQwiz и создавайте карточки с привязкой к источнику.</p><div class="panel book-drop"><div class="action-icon" style="margin:0 auto 10px">${icon('upload')}</div><h3>Добавить учебник</h3><p class="muted">PDF с текстовым слоем, DOCX или TXT. Сканированные страницы требуют OCR.</p><button class="btn primary" onclick="document.getElementById('bookFile').click()">Выбрать файл</button><input hidden id="bookFile" type="file" accept=".pdf,.docx,.txt"></div><div id="booksArea" class="book-list"></div>`;document.getElementById('bookFile').onchange=importBook;renderBooks();hydrateIcons()}
async function importBook(e){const f=e.target.files[0];if(!f)return;toast('Оцифровываю источник…');try{let text='';if(/\.txt$/i.test(f.name))text=await f.text();else if(/\.docx$/i.test(f.name)){await loadScript('https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.8.0/mammoth.browser.min.js');text=(await window.mammoth.extractRawText({arrayBuffer:await f.arrayBuffer()})).value}else if(/\.pdf$/i.test(f.name)){await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js');window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';const pdf=await pdfjsLib.getDocument({data:await f.arrayBuffer()}).promise;for(let i=1;i<=pdf.numPages;i++){const p=await pdf.getPage(i),c=await p.getTextContent();text+=`\n${c.items.map(x=>x.str).join(' ')}\n`}}else throw Error('Формат не поддерживается');if(!text.trim())throw Error('Текстовый слой не найден');const b={id:'book_'+Date.now(),name:f.name,size:f.size,created:now(),text,chapters:splitChapters(text)};await dbPut(b);toast(`Готово: ${b.chapters.length} разделов`);renderBooks()}catch(err){toast('Не удалось обработать: '+err.message)}}
function splitChapters(text){const lines=text.split(/\r?\n/),out=[];let cur={title:'Основной текст',text:''};for(const raw of lines){const l=raw.trim();if(!l)continue;const head=/^(глава|раздел|тема|лекция)\b/i.test(l)||(/^\d+(?:\.\d+)*[.)]?\s+/.test(l)&&l.length<110);if(head){if(cur.text.trim())out.push({...cur,text:cur.text.trim()});cur={title:l.replace(/^\d+(?:\.\d+)*[.)]?\s*/,'').trim(),text:''}}else cur.text+=(cur.text?'\n':'')+l}if(cur.text.trim())out.push({...cur,text:cur.text.trim()});return out.length?out:[{title:'Основной текст',text:text.trim()}]}
function renderBooks(){dbAll().then(bs=>{const el=document.getElementById('booksArea');if(!el)return;el.innerHTML=bs.length?bs.map(b=>`<div class="book-row"><div class="book-icon">${icon('book')}</div><main><h3>${esc(b.name)}</h3><p>${b.chapters.length} разделов · ${Math.round(b.size/1024)} КБ · ${new Date(b.created).toLocaleDateString('ru-RU')}</p></main><button class="btn" onclick="readBook('${b.id}')">Открыть</button><button class="btn danger" onclick="removeBook('${b.id}')">Удалить</button></div>`).join(''):'<div class="empty">Учебников пока нет.</div>';hydrateIcons()})}
async function readBook(id){const b=await dbGet(id);document.getElementById('view-textbook').innerHTML=`<div class="book-reader"><div class="book-head"><div><button class="btn soft" onclick="showView('textbook')">← Библиотека</button><h1 class="page-title" style="margin-top:12px">${esc(b.name)}</h1></div><select class="select" id="chapterSelect">${b.chapters.map((c,i)=>`<option value="${i}">${i+1}. ${esc(c.title)}</option>`).join('')}</select></div><div class="panel"><span class="eyebrow">ИСТОЧНИК</span><article id="bookText" class="book-text"></article><div style="margin-top:20px;display:flex;gap:8px"><button class="btn primary" id="chapterCards">Создать карточки из раздела</button></div></div></div>`;const render=()=>{const i=+document.getElementById('chapterSelect').value;document.getElementById('bookText').innerHTML=b.chapters[i].text.split(/\n+/).map(p=>`<p>${esc(p)}</p>`).join('');document.getElementById('chapterCards').onclick=()=>createFromChapter(b,i)};document.getElementById('chapterSelect').onchange=render;render()}
function createFromChapter(b,i){const cards=heuristicCards(b.chapters[i].text).map((c,n)=>({...c,id:`bookcard-${Date.now()}-${n}`,source:{name:b.name,chapterTitle:b.chapters[i].title}}));if(!cards.length){toast('В разделе недостаточно текста для автоматического выделения');return}state.customSets.unshift({id:'bookset-'+Date.now(),title:b.chapters[i].title,subject:'Учебник',description:`Источник: ${b.name}`,tags:['учебник'],cards});save();toast(`Создано карточек: ${cards.length}`);showView('sets')}
function heuristicCards(text){const parts=text.split(/[.!?]\s+/).filter(x=>x.length>45&&x.length<420).slice(0,40);return parts.map((p,i)=>{const words=p.trim().split(/\s+/);const term=words.slice(0,Math.min(7,words.length)).join(' ');return{q:`Что утверждается в этом фрагменте?`,a:p.trim(),tags:['учебник','автоматически'],term}})}
function createView(){document.getElementById('view-create').innerHTML=`<h1 class="page-title">Создать набор</h1><p class="page-sub">Создайте собственную базу знаний вручную или добавьте материал из учебника.</p><div class="panel"><div class="editor-grid"><div class="field"><label>Название набора</label><input id="newTitle" placeholder="Например: Височная кость"></div><div class="field"><label>Предмет</label><select id="newSubject">${SUBJECTS.map(x=>`<option>${x[0]}</option>`).join('')}<option>Учебник</option></select></div><div class="field" style="grid-column:1/-1"><label>Описание</label><textarea id="newDesc" placeholder="Кратко опишите содержание набора"></textarea></div></div><div class="section-head" style="margin-top:22px"><div><h3>Карточки</h3><p>Минимум один вопрос и один ответ.</p></div><button class="btn soft" onclick="addEditorCard()">${icon('plus')} Добавить карточку</button></div><div id="editorCards"></div><div style="margin-top:16px"><button class="btn primary" onclick="saveNewSet()">Создать набор</button></div></div>`;addEditorCard();addEditorCard();hydrateIcons()}
let editorN=0;function addEditorCard(q='',a=''){editorN++;const el=document.getElementById('editorCards');if(!el)return;const d=document.createElement('div');d.className='card-editor';d.innerHTML=`<div class="card-editor-head"><b>Карточка ${editorN}</b><button class="btn danger" onclick="this.closest('.card-editor').remove()">Удалить</button></div><div class="editor-grid" style="margin-top:10px"><div class="field"><label>Вопрос</label><textarea class="eq">${esc(q)}</textarea></div><div class="field"><label>Ответ</label><textarea class="ea">${esc(a)}</textarea></div></div>`;el.appendChild(d)}
function saveNewSet(){const title=document.getElementById('newTitle').value.trim(),subject=document.getElementById('newSubject').value,desc=document.getElementById('newDesc').value.trim();const cards=[...document.querySelectorAll('.card-editor')].map((x,i)=>({id:'custom-'+Date.now()+'-'+i,q:x.querySelector('.eq').value.trim(),a:x.querySelector('.ea').value.trim(),tags:[],source:null})).filter(x=>x.q&&x.a);if(!title||!cards.length){toast('Укажите название и заполните хотя бы одну карточку');return}state.customSets.unshift({id:'set-'+Date.now(),title,subject,description:desc||'Пользовательский набор',tags:[],cards});save();toast('Набор создан');showView('sets')}
function profileView(){document.getElementById('view-profile').innerHTML=`<h1 class="page-title">Профиль</h1><p class="page-sub">Настройки обучения и данные AlmazovQwiz.</p><div class="grid grid-2"><div class="panel"><div class="modal-brand"><span class="avatar" style="width:48px;height:48px">И</span><div><strong>Илья</strong><span>Студент</span></div></div><div class="settings-row"><span><b>Тема</b><small class="muted"> Светлая / тёмная / системная</small></span><select class="select" onchange="setTheme(this.value)"><option value="system">Системная</option><option value="light">Светлая</option><option value="dark">Тёмная</option></select></div><div class="settings-row"><span><b>Ежедневная цель</b><small class="muted"> Ответов в день</small></span><input class="select" style="width:90px" type="number" min="1" max="500" value="${state.profile.dailyGoal}" onchange="state.profile.dailyGoal=+this.value||20;save()"></div><div class="settings-row"><span><b>Напоминания</b><small class="muted"> Повторения и новые материалы</small></span><button class="switch ${state.profile.notifications?'on':''}" onclick="toggleSetting('notifications')"><span></span></button></div><div class="settings-row"><span><b>Автоповторение</b><small class="muted">Предлагать карточки по расписанию</small></span><button class="switch ${state.profile.autoRepeat?'on':''}" onclick="toggleSetting('autoRepeat')"><span></span></button></div></div><div class="panel"><h3>Данные</h3><p class="muted">Обычное обновление сохраняет учебную статистику. Сброс данных удаляет локальный прогресс и пользовательские наборы.</p><div style="display:grid;gap:8px"><button class="btn" onclick="exportData()">${icon('download')} Экспортировать резервную копию</button><button class="btn" onclick="clearCaches()">${icon('spark')} Обновить кэш приложения</button><button class="btn danger" onclick="resetData()">${icon('trash')} Сбросить локальные данные</button><button class="btn" onclick="window.open('https://t.me/R1vlFlow_GY','_blank')">${icon('telegram')} Поддержка в Telegram</button></div><p class="form-note">Версия 2.0.0 · проект не является официальным продуктом НМИЦ им. В. А. Алмазова.</p></div></div>`;hydrateIcons()}
function toggleSetting(k){state.profile[k]=!state.profile[k];save();profileView()} function setTheme(v){localStorage.setItem(THEME_KEY,v);state.theme=v;save();applyTheme();profileView()}
function helpView(){document.getElementById('view-help').innerHTML=`<h1 class="page-title">Помощь</h1><p class="page-sub">Основные принципы работы системы.</p><div class="grid grid-2"><div class="panel"><h3>Как считается прогресс?</h3><p class="muted">Только после ответа. Открытие карточки, просмотр набора и переход между разделами не изменяют статистику.</p><h3>Что такое «устойчивое знание»?</h3><p class="muted">Карточка считается устойчивой после серии успешных ответов. Это не процент, заданный вручную.</p><h3>Как работает повторение?</h3><p class="muted">После ответа система назначает следующий интервал. Ошибка возвращает карточку на короткий интервал.</p></div><div class="panel"><h3>Учебники</h3><p class="muted">PDF с текстовым слоем, DOCX и TXT можно оцифровать локально. Для сканов нужен OCR-модуль, которого в этой версии нет.</p><h3>Приватность</h3><p class="muted">Учебная статистика и пользовательские наборы хранятся локально в браузере. Серверной синхронизации в этой версии нет.</p></div></div>`}
function showView(v){document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));const el=document.getElementById('view-'+v);if(!el)return;el.classList.add('active');document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===v));if(v==='home')home();if(v==='sets')setsView();if(v==='textbook')textbookView();if(v==='study')studyView();if(v==='knowledge')knowledgeView();if(v==='analytics')analyticsView();if(v==='create')createView();if(v==='profile')profileView();if(v==='help')helpView();hydrateIcons();window.scrollTo({top:0,behavior:'smooth'});document.getElementById('sidebar').classList.remove('open')}
function exportData(){const blob=new Blob([JSON.stringify({version:APP_VERSION,state},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='almazovqwiz-backup.json';a.click();URL.revokeObjectURL(a.href);toast('Резервная копия подготовлена')}
function resetData(){if(!confirm('Удалить прогресс, пользовательские наборы и настройки?'))return;localStorage.removeItem('aq_state');location.reload()}
async function clearCaches(){if('caches' in window){const ks=await caches.keys();await Promise.all(ks.filter(k=>k.startsWith(CACHE_PREFIX)).map(k=>caches.delete(k)))}toast('Кэш приложения очищен');setTimeout(()=>location.reload(),300)}
function openDB(){return new Promise((res,rej)=>{const r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=()=>{const db=r.result;if(!db.objectStoreNames.contains('books'))db.createObjectStore('books',{keyPath:'id'})};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}async function dbPut(v){const db=await openDB();return new Promise((res,rej)=>{const t=db.transaction('books','readwrite');t.objectStore('books').put(v);t.oncomplete=res;t.onerror=()=>rej(t.error)})}async function dbGet(id){const db=await openDB();return new Promise((res,rej)=>{const r=db.transaction('books').objectStore('books').get(id);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}async function dbAll(){const db=await openDB();return new Promise((res,rej)=>{const r=db.transaction('books').objectStore('books').getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}async function removeBook(id){if(!confirm('Удалить учебник с устройства?'))return;const db=await openDB();await new Promise((res,rej)=>{const t=db.transaction('books','readwrite');t.objectStore('books').delete(id);t.oncomplete=res;t.onerror=()=>rej(t.error)});renderBooks();toast('Учебник удалён')}
function loadScript(src){return new Promise((res,rej)=>{const s=document.createElement('script');s.src=src;s.onload=res;s.onerror=()=>rej(new Error('Не удалось загрузить модуль обработки'));document.head.appendChild(s)})}
document.addEventListener('click',e=>{const v=e.target.closest('[data-view]');if(v){e.preventDefault();showView(v.dataset.view)}const t=e.target.closest('[data-action="telegram"]');if(t)window.open('https://t.me/R1vlFlow_GY','_blank')});document.getElementById('globalSearch').addEventListener('input',e=>{showView('sets');setsView(e.target.value)});document.getElementById('themeToggle').onclick=()=>setTheme(theme()==='dark'?'light':'dark');document.getElementById('mobileMenu').onclick=()=>document.getElementById('sidebar').classList.toggle('open');document.getElementById('dueBtn').onclick=startDue;document.getElementById('enterBeta').onclick=()=>{state.betaAccepted=true;save();document.getElementById('betaNotice').style.display='none'};
function boot(){applyTheme();hydrateIcons();home();if(state.betaAccepted)document.getElementById('betaNotice').style.display='none';if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});const prev=localStorage.getItem(BUILD_KEY);if(prev&&prev!==APP_VERSION){clearCaches().catch(()=>{});localStorage.setItem(BUILD_KEY,APP_VERSION)}else localStorage.setItem(BUILD_KEY,APP_VERSION)}boot();
